query_template:
PREFIX sb: <http://rdf.glycoinfo.org/SugarBind/ontology#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX dcterms: <http://purl.org/dc/terms/>
PREFIX foaf: <http://xmlns.com/foaf/0.1/>

SELECT ?interaction ?agent
       (GROUP_CONCAT(DISTINCT STR(?agent_label_value); separator=" | ") AS ?agent_label)
       (GROUP_CONCAT(DISTINCT STR(?agent_homepage_value); separator=" | ") AS ?agent_homepage)
       ?lectin
       (GROUP_CONCAT(DISTINCT STR(?lectin_label_value); separator=" | ") AS ?lectin_label)
       (GROUP_CONCAT(DISTINCT STR(?lectin_homepage_value); separator=" | ") AS ?lectin_homepage)
       (GROUP_CONCAT(DISTINCT STR(?uniprot_id_value); separator=" | ") AS ?uniprot_id)
       ?ligand
       (GROUP_CONCAT(DISTINCT STR(?ligand_label_value); separator=" | ") AS ?ligand_label)
       (GROUP_CONCAT(DISTINCT STR(?ligand_homepage_value); separator=" | ") AS ?ligand_homepage)
       (GROUP_CONCAT(DISTINCT STR(?structure_value); separator=" | ") AS ?structure)
       (GROUP_CONCAT(DISTINCT STR(?citation_value); separator=" | ") AS ?citation)
WHERE {{
    GRAPH <http://rdf.glycosmos.org/sugarbind> {{
        ?interaction a sb:ReferencedInteraction ;
                     sb:has_agent ?agent ;
                     sb:has_lectin ?lectin ;
                     sb:has_ligand ?ligand .
        OPTIONAL {{ ?interaction sb:has_citation ?citation_value . }}
        OPTIONAL {{ ?agent rdfs:label ?agent_label_value . }}
        OPTIONAL {{ ?agent foaf:homepage ?agent_homepage_value . }}
        OPTIONAL {{ ?lectin rdfs:label ?lectin_label_value . }}
        OPTIONAL {{ ?lectin foaf:homepage ?lectin_homepage_value . }}
        OPTIONAL {{ ?lectin sb:uniprotId ?uniprot_id_value . }}
        OPTIONAL {{ ?ligand rdfs:label ?ligand_label_value . }}
        OPTIONAL {{ ?ligand foaf:homepage ?ligand_homepage_value . }}
        OPTIONAL {{ ?ligand sb:has_structure ?structure_value . }}
    }}
}}
GROUP BY ?interaction ?agent ?lectin ?ligand
ORDER BY ?interaction ?ligand
LIMIT {limit}
OFFSET {offset}
